/* FIE V9.3 · first-class D/ST decision surface.
   Research complexity stays in the current snapshot; this module translates it
   into a compact league-specific weekly/streaming view and reuses canonical
   ownership/replacement concepts rather than inventing a separate value system. */
(function(){
'use strict';
let bundle=null,loading=false,error=null,leagueKey=null,selectedTeam=null;
const $=id=>document.getElementById(id);
const num=v=>Number.isFinite(Number(v))?Number(v):null;
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const f=(v,d=1)=>num(v)===null?'—':num(v).toFixed(d);
const signed=v=>num(v)===null?'—':`${num(v)>=0?'+':''}${f(v)}`;
function hasDST(){const c=window.FIELeagueContext?.current?.();return c?c.hasDST:(!!window.state?.league&&(state.league.roster_positions||[]).some(x=>['DEF','DST'].includes(String(x).toUpperCase())));}
function lid(){return String(window.state?.league?.league_id||'');}
function format(){try{return String(window.activeFormatKey?.()||'REDRAFT')}catch{return 'REDRAFT';}}
function rosterId(){return Number(window.state?.selectedRoster||0);}
function dstPlayers(){return (window.PLAYERS||[]).filter(p=>String(p.position||'').toUpperCase()==='DEF'&&p.leagueEligible!==false);}
function ownerStatus(p){if(Number(p.ownerRosterId)===rosterId()&&rosterId())return 'Yours';if(p.availability==='FA'||p.ownerRosterId==null)return 'FA';return p.owner||'Owned';}
function currentMap(){const m=new Map();for(const r of bundle?.players||[]){if(r.position_model!=='DEF')continue;for(const k of [r.sleeper_id,r.team,String(r.canonical_player_id||'').replace(/^DST:/,'')])if(k)m.set(String(k).toUpperCase(),r);}return m;}
function rowFor(p,m=currentMap()){return m.get(String(p.sleeperId||'').toUpperCase())||m.get(String(p.team||'').toUpperCase())||null;}
function meanFor(p,r){return num(r?.decision_weekly_projection)??num(p.weeklyProjection)??num(p.sleeperWeeklyProjection);}
function p10For(p,r){return num(r?.p10)??(p.rangeSource?.includes('empirical')?num(p.weeklyFloor):null);}
function p90For(p,r){return num(r?.p90)??(p.rangeSource?.includes('empirical')?num(p.weeklyCeiling):null);}
function decisionScore(x){const fmt=format(),mean=x.mean??-999,p10=x.p10??mean,p90=x.p90??mean;if(fmt==='CHOPPED')return .58*mean+.42*p10;if(fmt.includes('BESTBALL'))return .55*mean+.45*p90;return mean;}
function board(){const m=currentMap(),xs=dstPlayers().map(p=>{const r=rowFor(p,m),mean=meanFor(p,r),p10=p10For(p,r),p90=p90For(p,r),next3=num(r?.waiver_next3_projection),opp=r?.opponent||window.opponentFor?.(p)||'—';return{p,r,team:String(r?.team||p.team||p.sleeperId||'').toUpperCase(),mean,p10,p90,next3,opp,status:ownerStatus(p),active:r?.weekly_activation_eligible===true,source:r?.projection_source||p.m5ProjectionSource||'Sleeper baseline',score:0};}).filter(x=>x.team&&x.mean!==null);for(const x of xs)x.score=decisionScore(x);xs.sort((a,b)=>b.score-a.score);xs.forEach((x,i)=>x.rank=i+1);const n3=[...xs].filter(x=>x.next3!==null).sort((a,b)=>b.next3-a.next3);n3.forEach((x,i)=>x.next3Rank=i+1);return xs;}
function action(x,xs){const bestFA=xs.find(z=>z.status==='FA'),mine=xs.find(z=>z.status==='Yours');if(x.status==='Yours'){if(bestFA&&bestFA.mean!==null&&x.mean!==null&&bestFA.mean-x.mean>=1.75)return 'STREAM AWAY';return x.rank<=8?'START':'HOLD';}if(x.status!=='FA')return 'OWNED';if(x.rank<=5&&(!mine||x.mean-(mine.mean??-999)>=1.25))return 'STREAM';if(x.next3Rank&&x.next3Rank<=5&&x.rank>7)return 'STASH';if(x.rank<=12)return 'WATCH';return 'AVOID';}
function actionClass(a){return /START|STREAM/.test(a)?'positive':/STASH|HOLD|WATCH/.test(a)?'score mid':'negative';}
function replacement(xs){const svc=window.FIECore?.ReplacementService;if(!svc?.row||!xs.length)return null;const rows=xs.map(x=>({p:x.p,score:x.score,mean:x.mean}));const z=svc.row('DEF',rows,'score',{league:state.league,state});const rp=z?.row?.p;if(!rp)return null;return xs.find(x=>x.p===rp)||null;}
function modelLabel(xs){const active=xs.filter(x=>x.active).length;if(active)return `${active}/32 FIE-active`;if(xs.length)return 'Sleeper baseline · FIE validation gated off';return 'No D/ST projection rows';}
async function load(force=false){const k=lid();if(!k){bundle=null;return null;}if(!force&&bundle&&leagueKey===k)return bundle;if(loading)return bundle;loading=true;error=null;leagueKey=k;try{const rt=window.FIE_RESEARCH_RUNTIME,path=rt?.path?.('current/milestone5_current.json')||`data/research/leagues/${encodeURIComponent(k)}/current/milestone5_current.json`;const b=window.FIECurrentSnapshotStore?await window.FIECurrentSnapshotStore.load(path,{force}):await (async()=>{const r=await fetch(`${path}${force?'?t='+Date.now():''}`,{cache:force?'no-store':'default'});if(!r.ok)throw new Error(`HTTP ${r.status}`);return r.json();})();if(String(b.league_id||'')!==k)throw new Error('League namespace mismatch');bundle=b;}catch(e){error=String(e?.message||e);bundle=null;}finally{loading=false;}return bundle;}
function contextText(x){const c=x.r?.dst_context||{},parts=[];if(c.opponent_implied_points!=null)parts.push(`opp implied ${f(c.opponent_implied_points)} pts`);if(c.spread_line!=null){const s=num(c.spread_line);parts.push(s===0?'pick’em':`${s>0?'favored':'underdog'} ${Math.abs(s).toFixed(1)}`);}if(c.home===1)parts.push('home');else if(c.home===0)parts.push('away');return parts.join(' · ')||'Matchup context awaiting validated D/ST feed';}
function explain(x){const stats=x.r?.predicted_stats||{},keys=[['sack','Sacks'],['int','INT'],['fum_rec','Fumble rec.'],['def_td','D/ST TD'],['points_allowed','Points allowed'],['yards_allowed','Yards allowed']];return `<div class="notice" style="margin-top:12px"><b>${safe(x.team)} vs ${safe(x.opp)} · ${safe(action(x,board()))}</b><br>${safe(contextText(x))}<br><b>Projection source:</b> ${safe(x.source)}</div><div class="metrics" style="margin-top:10px">${keys.map(([k,l])=>`<div class="metric"><span class="muted">${l}</span><b>${stats[k]==null?'—':f(stats[k],k.includes('yards')?0:1)}</b></div>`).join('')}<div class="metric"><span class="muted">Week rank</span><b>#${x.rank}</b></div><div class="metric"><span class="muted">Next 3</span><b>${x.next3Rank?`#${x.next3Rank} · ${f(x.next3)}`:'—'}</b></div></div>${x.active?'':`<div class="notice" style="margin-top:10px"><b>Why no FIE override?</b> The D/ST research gate has not cleared for this stored bundle, so the app deliberately keeps Sleeper as the decision baseline rather than presenting an unvalidated model as production intelligence.</div>`}`;}
function render(){const st=$('dstStatus'),box=$('dstSummary');if(!st||!box)return;if(!state.league){st.textContent='Load a Sleeper league first.';box.innerHTML='';return;}if(!hasDST()){st.textContent='This league does not roster a team D/ST, so D/ST intelligence is intentionally disabled.';box.innerHTML='';return;}if((!bundle||leagueKey!==lid())&&!loading){st.textContent='Loading league-specific D/ST snapshot…';load().then(()=>{if(state.activeTab==='dst')render();});return;}if(loading){st.textContent='Loading league-specific D/ST snapshot…';return;}const xs=board();if(!xs.length){st.textContent=error?`D/ST snapshot unavailable: ${error}`:'No D/ST projections are available for this week.';box.innerHTML='<div class="notice" style="margin-top:12px">The rest of the app remains available. D/ST stays fail-closed until a valid weekly baseline is present.</div>';return;}const mine=xs.find(x=>x.status==='Yours'),bestFA=xs.find(x=>x.status==='FA'),stash=[...xs].filter(x=>x.status==='FA'&&x.next3!==null).sort((a,b)=>b.next3-a.next3)[0],repl=replacement(xs),fmt=format();st.innerHTML=`<b>${safe(state.league.name||state.league.league_name||'Loaded league')}</b> · ${xs.length} D/ST · ${safe(modelLabel(xs))} · ${safe(fmt.replaceAll('_',' '))}. ${fmt==='CHOPPED'?'Ranking emphasizes downside protection.':fmt.includes('BESTBALL')?'Ranking gives extra weight to ceiling.':'Ranking emphasizes expected weekly points.'}`;const card=(label,x,sub)=>`<div class="intel-card"><span class="filter-label">${label}</span><div class="big">${x?safe(x.team):'—'}</div><div class="tiny">${x?`${f(x.mean)} pts · #${x.rank}${sub?` · ${safe(sub)}`:''}`:'No eligible option'}</div></div>`;box.innerHTML=`<div class="intel-grid">${card('Your D/ST',mine,mine?action(mine,xs):'')}${card('Best available',bestFA,bestFA?action(bestFA,xs):'')}${card('Best stash',stash,stash?.next3Rank?`Next 3 #${stash.next3Rank}`:'')}${card('Replacement line',repl,repl?'canonical replacement cutoff':'')}</div><div class="notice"><b>Read this board in order:</b> Action first, then expected points, then Low/High when FIE uncertainty is validated. “Next 3” is a stash/hold signal, not a substitute for this week's matchup.</div><div class="table-wrap" style="margin-top:12px"><table class="m1-table fie93-table"><thead><tr><th>Rank</th><th>D/ST</th><th>Opp</th><th>Status</th><th>Week Proj</th><th>Low / High</th><th>vs Replacement</th><th>Next 3</th><th>Action</th></tr></thead><tbody>${xs.map(x=>{const a=action(x,xs),rv=repl?.mean==null?null:x.mean-repl.mean;return `<tr data-dst-team="${safe(x.team)}"><td><b>#${x.rank}</b></td><td><b>${safe(x.team)}</b></td><td>${safe(x.opp)}</td><td>${safe(x.status)}</td><td class="score"><b>${f(x.mean)}</b></td><td>${x.p10==null&&x.p90==null?'—':`${f(x.p10)} / ${f(x.p90)}`}</td><td>${signed(rv)}</td><td>${x.next3Rank?`#${x.next3Rank} · ${f(x.next3)}`:'—'}</td><td class="${actionClass(a)}"><b>${safe(a)}</b></td></tr>`}).join('')}</tbody></table></div><div id="dstDetail">${explain(xs.find(x=>x.team===selectedTeam)||mine||bestFA||xs[0])}</div>`;for(const tr of box.querySelectorAll('[data-dst-team]'))tr.onclick=()=>{selectedTeam=tr.dataset.dstTeam;const x=xs.find(z=>z.team===selectedTeam);const d=$('dstDetail');if(x&&d)d.innerHTML=explain(x);};}
function refresh(){bundle=null;leagueKey=null;return load(true).then(render);}
window.FIEDST={render,refresh,load,hasDST,board};
})();
